<?php
sessionOpen();$booking=null;$message='We’re checking your payment. Your booking will appear once Stripe confirms payment.';$sessionId=(string)($_GET['session_id']??'');$pending=getRecord('checkout',$_SESSION['checkoutId']??'');if($pending&&preg_match('/^cs_(test|live)_[a-zA-Z0-9]+$/',$sessionId)&&hash_equals($pending['sessionToken']??'',$_SESSION['checkoutToken']??'')&&hash_equals($pending['sessionId']??'',$sessionId)){try{$s=stripeRequest('GET','checkout/sessions/'.rawurlencode($sessionId));$booking=completePayment($s);if($booking){sendBookingReceipt($booking);foreach($booking['cartIds']??[] as $cartId)unset($_SESSION['cart'][$cartId]);}elseif(($s['payment_status']??'')==='unpaid')$message='Payment has not been confirmed yet. If you completed checkout, please contact our team with your payment details.';}catch(Throwable){$message='We couldn’t check your payment right now. Please contact our team if you have completed checkout.';}}else $message='Your booking receipt is shown here after a verified payment. Explore our experiences to start a new booking.';ob_start();?><section class="thank-you"><div class="success-icon"><?=icon($booking?'check':'shield')?></div><span class="eyebrow"><?=$booking?'Payment received':'Your booking'?></span><h1><?=$booking?'Your next adventure is on its way.':'Let’s check your next adventure.'?></h1><p><?=$booking?'Thank you for choosing Desert Sky Tourism. We’ve received your payment and our team will confirm your tour arrangements separately.':esc($message)?></p><?php if($booking):?><div class="form-panel"><div class="summary-lines"><div><span>Booking reference</span><strong><?=esc($booking['reference'])?></strong></div><div><span>Experience</span><strong><?=esc($booking['tourTitle'])?></strong></div><div><span>Tour date</span><strong><?=esc($booking['date'])?></strong></div><div><span>Guests</span><strong><?=$booking['adults']+$booking['children']?></strong></div><div><span>Payment</span><strong><?=money($booking['total'])?> · Paid<?=$booking['mode']==='test'?' (test)':''?></strong></div></div></div><?php if(!empty($booking['items'])):foreach($booking['items'] as $item):?><p><?=esc($item['tourTitle'])?> · <?=esc($item['date'])?> · <?=money($item['total'])?></p><?php endforeach;endif;if(customer()):?><a class="button button-outline" href="/account">View my bookings</a><?php endif;endif;?><a href="/tours" class="button">Keep exploring <?=icon()?></a><p class="muted" style="margin-top:25px">Need a hand? <a href="/contact">Contact our team</a>.</p></section><?php renderPage($booking?'Thank you for your booking | Desert Sky Tourism':'Booking payment | Desert Sky Tourism','Your secure booking confirmation.',ob_get_clean(),[],true);exit;
